from __future__ import annotations

import json
from pathlib import Path

from workflow.characterize_sample import run_public_observations


TASK_DIR = Path(__file__).resolve().parent
REPORT_FILE = TASK_DIR / "outputs" / "public_reproduction_report.json"


def write_report(report: dict[str, object], exit_code: int) -> int:
    REPORT_FILE.parent.mkdir(exist_ok=True)
    payload = json.dumps(report, indent=2, sort_keys=True) + "\n"
    REPORT_FILE.write_text(payload, encoding="utf-8")
    print(payload, end="")
    return exit_code


def main() -> int:
    try:
        observations = run_public_observations()
    except Exception as exc:  # noqa: BLE001 - report infrastructure separately.
        return write_report(
            {
                "schema_version": "1.3",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    invariant = bool(observations["representation_invariant"])
    report = {
        "schema_version": "1.3",
        "status": "post_fix_success" if invariant else "pre_fix_expected_failure",
        "observation": observations,
    }
    return write_report(report, 0 if invariant else 1)


if __name__ == "__main__":
    raise SystemExit(main())

